/**
 * Compile-time check that the client's validated types describe the same
 * fields as the server's Rust structs (generated into ./generated by
 * `cargo test`). The client may narrow a field (for example metadataSource
 * to 'tmdb' | 'tvmaze'), but a field added or removed on one side only stops
 * `tsc` here instead of failing at runtime on a TV.
 */
import type {
  Media as ClientMedia,
  Playback as ClientPlayback,
} from '../../contracts/index.ts';
import type { ContinueItem as ClientContinueItem } from './continue.ts';
import type { ContinueItem as ServerContinueItem } from './generated/ContinueItem.ts';
import type { Media as ServerMedia } from './generated/Media.ts';
import type { Playback as ServerPlayback } from './generated/Playback.ts';
import type { Progress as ServerProgress } from './generated/Progress.ts';
import type { Progress as ClientProgress } from './progress-types.ts';

type SameFields<A, B> = [
  Exclude<keyof A, keyof B>,
  Exclude<keyof B, keyof A>,
] extends [never, never]
  ? true
  : { missing: Exclude<keyof B, keyof A>; extra: Exclude<keyof A, keyof B> };

export const contractMatches: [
  SameFields<ServerMedia, ClientMedia>,
  SameFields<ServerPlayback, ClientPlayback>,
  SameFields<ServerProgress, ClientProgress>,
  SameFields<ServerContinueItem, ClientContinueItem>,
] = [true, true, true, true];
